import pathlib,json,os
p=pathlib.Path('/home/appontrack/.ontrack-mobile/pilot')
out={'pilot_store_exists':p.exists(),'stats':{},'auth_file_exists':pathlib.Path('/home/appontrack/public_html/saas/mobile/server/auth.sha256').exists()}
for kind in ('contacts','campaigns','attempts','dnc'):
 f=p/(kind+'.json')
 try:
  v=json.loads(f.read_text()) if f.is_file() else []
  out['stats'][kind]={'count':len(v) if isinstance(v,list) else None,'bytes':f.stat().st_size if f.is_file() else 0}
 except Exception as e:out['stats'][kind]={'error':type(e).__name__}
print(json.dumps(out,ensure_ascii=False))
